// The purchasing mailbox receives requests written on the template below.
// Each "Label: value" line fills one field; attachments are recognised by
// their file name (quote, bid comparison, award, single source, CapEx, spec).
const email = $json;
const labels = {
  'reference': 'external_ref', 'department': 'department', 'supplier': 'supplier_id',
  'category': 'item_category', 'item code': 'item_code', 'description': 'description',
  'quantity': 'quantity', 'unit price': 'unit_price', 'currency': 'currency',
  'justification': 'justification', 'needed by': 'delivery_date', 'capex': 'is_capex',
};
const payload = { attachments: [], is_capex: false };
for (const line of (email.Text || '').split(/\r?\n/)) {
  const match = line.match(/^\s*([A-Za-z ]+?)\s*:\s*(.+?)\s*$/);
  if (!match) continue;
  const key = labels[match[1].toLowerCase()];
  if (!key) continue;
  payload[key] = key === 'is_capex' ? /^(yes|true|oui|1)$/i.test(match[2]) : match[2];
}
if (payload.currency) payload.currency = payload.currency.toUpperCase();
if (payload.quantity) payload.quantity = payload.quantity.replace(',', '.');
if (payload.unit_price) payload.unit_price = payload.unit_price.replace(/\s/g, '').replace(',', '.');
const kinds = [
  [/quote|devis|offer/i, 'quote'], [/bid|comparison|comparatif/i, 'bid_comparison'],
  [/award/i, 'award_decision'], [/single.?source|ssj/i, 'single_source_justification'],
  [/capex/i, 'capex_approval'], [/spec/i, 'specification'],
];
const ignored = [];
for (const file of email.Attachments || []) {
  const kind = kinds.find(([pattern]) => pattern.test(file.FileName));
  if (kind) payload.attachments.push({ kind: kind[1], file_name: file.FileName });
  else ignored.push(file.FileName);
}
const sender = (email.From || {}).Address || '';
return {
  json: {
    ready: Boolean(payload.external_ref && sender),
    payload,
    ignored,
    sender,
    senderName: (email.From || {}).Name || sender,
    subject: email.Subject || '',
    messageId: email.MessageID || email.ID,
    mailpitId: email.ID,
  },
};

// Turn the answer of NEXORA into a reply to the sender.
const email = $('Parse the request form').item.json;
const status = $json.statusCode;
const body = $json.body || {};
const ref = email.payload.external_ref;
let subject, text;
if (status === 201 || status === 200) {
  const flags = (body.checks || []).filter(c => c.outcome === 'flag');
  const who = body.route === 'approver' ? 'the Head of Procurement' : 'a category buyer';
  subject = status === 201 ? `Received: ${ref}` : `Already received: ${ref}`;
  text = `Hello ${email.senderName.split(' ')[0]},\n\n` + (status === 201
      ? `Your purchase request ${ref} was received and checked.`
      : `Your purchase request ${ref} had already been received; it was not submitted twice.`)
    + `\n\nAmount: ${Number(body.amount).toFixed(2)} ${body.currency}. It will be reviewed by ${who}.`
    + (flags.length
      ? '\n\nPoints the reviewer will look at:\n' + flags.map(f => `- ${f.message}`).join('\n')
      : '\n\nNo rule raised a finding.')
    + (email.ignored.length ? `\n\nFiles not recognised: ${email.ignored.join(', ')}.` : '')
    + `\n\nFollow it: ${$env.NEXORA_UI_URL}/?request=${body.id}`;
} else {
  const detail = body.detail || {};
  const errors = (detail.errors || []).map(e => `- ${e.field || 'request'}: ${e.message}`);
  subject = `Not submitted: ${ref}`;
  text = `Hello ${email.senderName.split(' ')[0]},\n\n`
    + `Your purchase request ${ref} could not be submitted.\n\n`
    + (detail.message || `The service answered HTTP ${status}.`)
    + (errors.length ? '\n' + errors.join('\n') : '')
    + '\n\nCorrect the email and send it again.';
}
return { json: { to: email.sender, subject: `[NEXORA] ${subject}`, text } };
